from itertools import combinations

from rules import allowed


def solve(data):
    blocked = set(data.get("blocked", []))
    options = [job for job in data["jobs"] if job["id"] not in blocked]
    k = data["k"]

    best_ids = None
    best_value = None
    for choice in combinations(options, k):
        if not allowed(choice, data):
            continue
        ids = sorted(job["id"] for job in choice)
        value = sum(job["value"] for job in choice)
        if (best_value is None or value > best_value
                or (value == best_value and ids < best_ids)):
            best_value = value
            best_ids = ids

    if best_ids is None:
        return {"error": "impossible"}
    return {"selected": best_ids, "value": best_value}

from collections import Counter

POLICY = {"capacity": 1, "tie": "smallest"}


def allowed(selected, data):
    ids = {job["id"] for job in selected}
    if not set(data.get("mandatory", [])).issubset(ids):
        return False

    counts = Counter(job["group"] for job in selected)
    for group, (low, high) in data.get("quotas", {}).items():
        if not low <= counts[group] <= high:
            return False

    previous_end = None
    for job in sorted(selected, key=lambda row: (row["start"], row["end"], row["id"])):
        if previous_end is not None and job["start"] < previous_end:
            return False
        previous_end = job["end"]
    return True
